<?php
namespace App\Filament\Resources\Settings;
use App\Filament\Resources\Concerns\AdminResource;use App\Filament\Resources\Settings\Pages\ManageStoreSettings;use App\Models\StoreSetting;
use BackedEnum;use Filament\Actions\EditAction;use Filament\Forms\Components\Textarea;use Filament\Forms\Components\TextInput;use Filament\Schemas\Schema;use Filament\Support\Icons\Heroicon;use Filament\Tables\Columns\TextColumn;use Filament\Tables\Table;
class StoreSettingResource extends AdminResource {protected static ?string $model=StoreSetting::class;protected static string $viewPermission='settings.manage';protected static ?string $managePermission='settings.manage';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedCog6Tooth;protected static ?string $navigationLabel='Cài đặt cửa hàng';protected static string|\UnitEnum|null $navigationGroup='Hệ thống';protected static ?int $navigationSort=40;public static function form(Schema $s):Schema{return $s->components([TextInput::make('key')->label('Khóa cài đặt')->required()->unique(ignoreRecord:true)->disabledOn('edit'),Textarea::make('value')->label('Giá trị')->required()->rows(4)]);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('key')->label('Cài đặt')->searchable()->weight('bold'),TextColumn::make('value')->label('Giá trị')->limit(80),TextColumn::make('updated_at')->label('Cập nhật')->dateTime('d/m/Y H:i')])->recordActions([EditAction::make()->label('Sửa')]);}public static function canCreate():bool{return false;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function getPages():array{return ['index'=>ManageStoreSettings::route('/')];}}
